package android.view.inputmethod;
import android.os.Bundle;
import android.view.KeyEvent;
public class InputConnectionWrapper implements InputConnection {
    private InputConnection target; private final boolean mutable;
    public InputConnectionWrapper(InputConnection target,boolean mutable){this.target=target;this.mutable=mutable;}
    public void setTarget(InputConnection target){if(this.target!=null&&!mutable)throw new SecurityException();this.target=target;}
    public CharSequence getTextBeforeCursor(int n,int f){return target==null?null:target.getTextBeforeCursor(n,f);} public CharSequence getTextAfterCursor(int n,int f){return target==null?null:target.getTextAfterCursor(n,f);} public CharSequence getSelectedText(int f){return target==null?null:target.getSelectedText(f);} public int getCursorCapsMode(int m){return target==null?0:target.getCursorCapsMode(m);}
    public boolean commitText(CharSequence t,int p){return target!=null&&target.commitText(t,p);} public boolean setComposingText(CharSequence t,int p){return target!=null&&target.setComposingText(t,p);} public boolean finishComposingText(){return target!=null&&target.finishComposingText();} public boolean setSelection(int s,int e){return target!=null&&target.setSelection(s,e);} public boolean deleteSurroundingText(int a,int b){return target!=null&&target.deleteSurroundingText(a,b);} public boolean sendKeyEvent(KeyEvent e){return target!=null&&target.sendKeyEvent(e);} public boolean performEditorAction(int a){return target!=null&&target.performEditorAction(a);} public boolean performContextMenuAction(int a){return target!=null&&target.performContextMenuAction(a);} public boolean beginBatchEdit(){return target!=null&&target.beginBatchEdit();} public boolean endBatchEdit(){return target!=null&&target.endBatchEdit();} public boolean performPrivateCommand(String a,Bundle b){return target!=null&&target.performPrivateCommand(a,b);} public boolean commitContent(InputContentInfo c,int f,Bundle b){return target!=null&&target.commitContent(c,f,b);}
}
